const acorn = require('acorn')
const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '..')
const scriptRoot = path.join(root, 'app', 'assets', 'js', 'scripts')
const output = path.join(root, 'app', 'assets', 'js', 'privileged-ui.bundle.js')
const scriptNames = [
    'uicore.js',
    'uibinder.js',
    'welcome.js',
    'login.js',
    'loginOptions.js',
    'settings.js',
    'landing.js',
    'overlay.js'
]

function transformTopLevelDeclarations(source, filename){
    const normalized = source.replace(/^\uFEFF/, '')
    const ast = acorn.parse(normalized, {
        ecmaVersion: 2022,
        sourceType: 'script',
        allowHashBang: true
    })
    const replacements = ast.body
        .filter(node => node.type === 'VariableDeclaration' && node.kind !== 'var')
        .map(node => ({ start: node.start, end: node.start + node.kind.length }))
        .sort((a, b) => b.start - a.start)

    let transformed = normalized
    for(const replacement of replacements){
        transformed = transformed.slice(0, replacement.start) + 'var' + transformed.slice(replacement.end)
    }
    return `\n// Source: ${filename}\n${transformed}`
}

const sources = scriptNames.map(filename => {
    const source = fs.readFileSync(path.join(scriptRoot, filename), 'utf8')
    return transformTopLevelDeclarations(source, filename)
})
const banner = '// Generated by scripts/build-preload-bundle.js. Do not edit directly.\n'
const bundle = `${banner}module.exports = function(require, module, exports, __dirname, __filename, remote, shell, runtimeInfo) {${sources.join('\n')}\n}\n`
fs.writeFileSync(output, bundle)
console.log(`Generated ${path.relative(root, output)}.`)
